pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address logger, bool status, bool initialStatus) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(c));
        vm.assume(logger != address(0));
        vm.assume(initialStatus != status);

        // Set initial state via the contract itself (msg.sender is this test contract which deploys C; 
        // typically deployer is not set as owner, but we need to set owner first to establish baseline.
        // Since the bug is in the modifier, we call setApprovedLogger as the test contract to set owner
        // and then set the initial approvedLoggers state as the owner.
        // Actually, _contractOwner is never set in the provided code. The contract has no constructor.
        // So _contractOwner is address(0) initially and onlyOwner checks msg.sender == address(0) which is impossible.
        // But the bug changes the modifier to require(true). So the reference cannot set approvedLoggers at all.
        // However, the property we test is: for any non-owner (i.e., anyone), calling setApprovedLogger
        // should NOT change the mapping value from its initial state (or from whatever state the owner sets).
        // Since we can't set the owner in the reference without a constructor, we just test that a non-zero
        // address (nonOwner) cannot change the mapping from false to true or vice versa in the reference,
        // but can in the buggy version.

        // Record initial value
        bool beforeVal = c.approvedLoggers(logger);

        vm.prank(nonOwner);
        bool result;
        try c.setApprovedLogger(logger, status) { result = true; } catch { result = false; }

        bool afterVal = c.approvedLoggers(logger);

        // For reference: if the call reverted (result=false) then afterVal must equal beforeVal.
        // If the call succeeded (result=true) but the modifier was correctly onlyOwner, it would revert for nonOwner
        // because nonOwner != _contractOwner (address(0)). Since there's no way to set _contractOwner,
        // the reference always reverts for any msg.sender != address(0). So the reference should always revert.
        // But in the buggy version, require(true) always passes, so the call succeeds and changes the mapping.

        // The property: if a non-owner (anyone) calls setApprovedLogger, the mapping should NOT change.
        // In the reference, call reverts -> mapping unchanged. In buggy, call succeeds -> mapping changes (since status != beforeVal).
        // We assert that if the call succeeded, the mapping must not have changed.
        // However, we need a single assertTrue that holds for reference for ALL inputs and fails for buggy for SOME.
        // In reference, call always reverts, so result is false, and beforeVal == afterVal (unchanged).
        // In buggy, call succeeds (result true), and if status != beforeVal, mapping changes -> beforeVal != afterVal.
        // But if we choose status == beforeVal, mapping stays same even in buggy. The fuzzer can choose status != beforeVal
        // to make the bug manifest. So we assert: if result is true, then beforeVal == afterVal.
        // Reference: result always false, so implication vacuously true.
        // Buggy: there exists inputs (status != beforeVal) where result true and beforeVal != afterVal, so assertion fails.

        assertTrue(!result || beforeVal == afterVal);
    }
}

