pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address logger, bool status, address caller) public {
        // Owner can set loggers; we restrict caller to be the owner.
        vm.prank(caller);
        try c.owner() returns (address ownerAddr) {
            vm.assume(caller == ownerAddr);
        } catch {
            // If owner() doesn't exist, we can't guarantee the setup;
            // the original contract has no owner() method, only private _contractOwner.
            // So we skip this approach.
        }

        // Set up: make the caller the owner by deploying with the owner being the test contract.
        // Since _contractOwner is private and set in constructor, we can't change it.
        // Therefore, the only admissible caller is the address that deploys the contract.
        // In setUp(), `c = new C()` sets `_contractOwner = address(this)`.
        // So the only valid caller for onlyOwner functions is address(this).
        vm.assume(caller == address(this));

        // Call setApprovedLogger with the fuzzed logger and status.
        c.setApprovedLogger(logger, status);

        // After the call, approvedLoggers[logger] must equal the _status argument for the reference,
        // but the bug always sets it to false.
        // We cannot call approvedLoggers directly because it's public and auto-generated getter exists.
        bool actual = c.approvedLoggers(logger);

        // The reference rule: if status is true, actual must be true; if status is false, actual must be false.
        // The bug breaks when status is true.
        assertTrue(actual == status);
    }
}

