        vm.assume(logger != address(0));
        vm.assume(keepAddress != address(0));

        // 2. Owner (this contract) sets logger as approved with _status=true.
        c.setApprovedLogger(logger, true);

        // 3. Logger calls logCreated. The callers approveAndLog must succeed on the correct contract.
        bool success;
        vm.prank(logger);
        success = c.logCreated(keepAddress);

        // 4. Assert: The reference contract returns true because logger IS approved.
        //    The mutant returns false because setApprovedLogger always writes false.
        assertTrue(success);
    }
}

