pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, address other, bool flag) public {
        // keep target and other distinct so the two calls don't alias
        vm.assume(target != other);

        // 1. approve nothing at first
        // 2. as owner, try to revoke (or keep revoked) target
        vm.prank(address(c).call(abi.encodeWithSignature("owner()")) ? address(c).call(abi.encodeWithSignature("owner()")) : address(this));
        // Since owner is not public, we simply set the contract deployer as owner by pranking;
        // the deployer is the default owner.
        c.setApprovedLogger(target, false);

        // target must NOT be approved after a false call
        bool targetApprovedAfterFalse = c.approvedToLog(target);

        // 3. now call setApprovedLogger on a different address with any flag
        vm.prank(address(this));
        c.setApprovedLogger(other, flag);

        // target's approval remains unchanged after the second operation
        bool targetApprovedAfterSecond = c.approvedToLog(target);

        // The rule: after a false call on target, target stays unapproved regardless of later operations on other addresses
        assertTrue(!targetApprovedAfterFalse && !targetApprovedAfterSecond);
    }
}
